{
  "interpretation": {
    "name": "TightenVariantOnLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 on line 2 with the shared nutrunner NR7, then return the tool to the crib.",
    "constraints": [
      "The tool is reserved before use and released at the end (E1, E6)",
      "The tool is at station st2 before configure-tool and tighten-fasteners (E3)",
      "The program comes only from get-program (E4)",
      "The tightening is evaluated and recorded (E5)",
      "transport-tool is delegated to agvexecutor (E2)",
      "The tool is returned to the crib at the end"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "once, for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-f30-tighten-and-return",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "BringTool",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "BringTool",
        "next": "Tighten",
        "steps": [
          {"name": "to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "Quality",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten"], "dep": ["program", "reserve", "to-station"], "executor": null, "params": {}},
          {"name": "tighten", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Quality",
        "next": "ReturnTool",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "ReturnTool",
        "next": null,
        "steps": [
          {"name": "to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
